  const STAGE_NAMES = {
    '4546923': 'Opportunities',
    '4546927': 'Quote Sent',
    '1337550105': 'Stale/Expired Quote',
    '4546928': 'Closed Won (Invoice Sent)',
    '943265375': 'Hold'
  };

  const deals = $input.all().map(i => i.json);
  const today = new Date().toISOString().slice(0, 10);
  const now = new Date();

  const openDeals = deals.filter(d =>
    d.hs_is_closed_won !== 'true' && d.dealstage !== 'closedlost'
  );

  return openDeals.map(d => {
    const created = new Date(d.createdate);
    const daysInStage = d.hs_lastmodifieddate
      ? Math.floor((now - new Date(d.hs_lastmodifieddate)) / 86400000)
      : Math.floor((now - created) / 86400000);

    return {
      json: {
        rep_id: 'kinga',
        deal_id: d.deal_id || d.hs_object_id,
        deal_name: d.dealname,
        stage: STAGE_NAMES[d.dealstage] || d.dealstage,
        value: parseFloat(d.amount || 0),
        days_in_stage: daysInStage,
        last_stage_change: d.hs_lastmodifieddate || d.createdate,
        snapshot_date: today
      }
    };
  });

