const invoices = invoiceResp.QueryResponse?.Invoice || [];
const custMap = $('Postgres — Fetch Customer Map').all().map(i => i.json);

const repCusts = custMap.filter(m => m.rep_id === REP_ID);
const repCustIds = new Set(repCusts.map(m => m.qbo_customer_id));
const custVertical = Object.fromEntries(
  repCusts.map(m => [m.qbo_customer_id, m.vertical])
);
const custName = Object.fromEntries(
  repCusts.map(m => [m.qbo_customer_id, m.qbo_customer_name])
);

const now = new Date();
const yearStart = new Date(now.getFullYear(), 0, 1);
const qtrMonth = Math.floor(now.getMonth() / 3) * 3;
const qtrStart = new Date(now.getFullYear(), qtrMonth, 1);
const today = now.toISOString().slice(0, 10);

function productRevenue(inv) {
  return (inv.Line || [])
    .filter(l => l.DetailType === 'SalesItemLineDetail')
    .filter(l => {
      const ref = l.SalesItemLineDetail?.ItemAccountRef?.name || '';
      return ref.includes('41000') || ref.includes('43000') ||
             ref.includes('44000') || ref.includes('45000');
    })
    .reduce((sum, l) => sum + parseFloat(l.Amount || 0), 0);
}

// Group by customer (distributor = customer in this context)
const byCustomer = {};
for (const inv of invoices) {
  const cid = String(inv.CustomerRef?.value);
  if (!repCustIds.has(cid)) continue;
  if (!byCustomer[cid]) byCustomer[cid] = { ytd: 0, qtd: 0, deals: 0 };
  const rev = productRevenue(inv);
  const d = new Date(inv.TxnDate);
  if (d >= yearStart) { byCustomer[cid].ytd += rev; byCustomer[cid].deals++; }
  if (d >= qtrStart) { byCustomer[cid].qtd += rev; }
}

return Object.entries(byCustomer).map(([cid, data]) => ({
  json: {
    rep_id: REP_ID,
    distributor_name: custName[cid] || cid,
    sector: custVertical[cid] || 'Unknown',
    revenue_ytd: Math.round(data.ytd * 100) / 100,
    revenue_qtd: Math.round(data.qtd * 100) / 100,
    deals_ytd: data.deals,
    mom_growth: 0,
    snapshot_date: today
  }
}));

