// PETE — Product Breakdown
// ═══════════════════════════════════════════
const REP_ID = 'pete';
const invoiceResp = $('QuickBooks — Fetch Invoices YTD').first().json;
const invoices = invoiceResp.QueryResponse?.Invoice || [];
const custMap = $('Postgres — Fetch Customer Map').all().map(i => i.json);

const repCustIds = new Set(
  custMap.filter(m => m.rep_id === REP_ID).map(m => m.qbo_customer_id)
);

const now = new Date();
const yearStart = new Date(now.getFullYear(), 0, 1);
const today = now.toISOString().slice(0, 10);

// Account code to product line mapping
const PRODUCTS = {
  '41000': 'Devices',
  '44000': 'Strips',
  '43000': 'Sweat Tests',
  '45000': 'Accessories'
};

const totals = {};
for (const key of Object.keys(PRODUCTS)) {
  totals[key] = { units: 0, revenue: 0 };
}

for (const inv of invoices) {
  const cid = String(inv.CustomerRef?.value);
  if (!repCustIds.has(cid)) continue;
  if (new Date(inv.TxnDate) < yearStart) continue;

  for (const line of (inv.Line || [])) {
    if (line.DetailType !== 'SalesItemLineDetail') continue;
    const acctName = line.SalesItemLineDetail?.ItemAccountRef?.name || '';
    for (const [code, label] of Object.entries(PRODUCTS)) {
      if (acctName.includes(code)) {
        totals[code].revenue += parseFloat(line.Amount || 0);
        totals[code].units += parseFloat(line.SalesItemLineDetail?.Qty || 0);
      }
    }
  }
}

return Object.entries(PRODUCTS).map(([code, label]) => ({
  json: {
    rep_id: REP_ID,
    snapshot_date: today,
    product_line: label,
    units_sold_ytd: Math.round(totals[code].units),
    revenue_ytd: Math.round(totals[code].revenue * 100) / 100,
    yoy_growth: 0
  }
}));

// ═══════════════════════════════════════════
// PETE — Fallen Angels (inactive 90+ days)
// ═══════════════════════════════════════════
const REP_ID = 'pete';
const invoiceResp = $('QuickBooks — Fetch Invoices YTD').first().json;
const invoices = invoiceResp.QueryResponse?.Invoice || [];
const custMap = $('Postgres — Fetch Customer Map').all().map(i => i.json);

const repCusts = custMap.filter(m => m.rep_id === REP_ID);
const repCustIds = new Set(repCusts.map(m => m.qbo_customer_id));
const custNameMap = Object.fromEntries(
  repCusts.map(m => [m.qbo_customer_id, m.qbo_customer_name])
);

const now = new Date();
const today = now.toISOString().slice(0, 10);
const NINETY_DAYS_AGO = new Date(now);
NINETY_DAYS_AGO.setDate(now.getDate() - 90);

function productRevenue(inv) {
  return (inv.Line || [])
    .filter(l => l.DetailType === 'SalesItemLineDetail')
    .filter(l => {
      const ref = l.SalesItemLineDetail?.ItemAccountRef?.name || '';
      return ref.includes('41000') || ref.includes('43000') ||
             ref.includes('44000') || ref.includes('45000');
    })
    .reduce((sum, l) => sum + parseFloat(l.Amount || 0), 0);
}

// Build customer purchase history
const custHistory = {};
for (const inv of invoices) {
  const cid = String(inv.CustomerRef?.value);
  if (!repCustIds.has(cid)) continue;
  if (!custHistory[cid]) custHistory[cid] = { lastDate: null, totalRev: 0 };
  const d = new Date(inv.TxnDate);
  if (!custHistory[cid].lastDate || d > custHistory[cid].lastDate) {
    custHistory[cid].lastDate = d;
  }
  custHistory[cid].totalRev += productRevenue(inv);
}

// Filter to customers whose last purchase was 90+ days ago
const fallenAngels = Object.entries(custHistory)
  .filter(([cid, data]) => data.lastDate && data.lastDate < NINETY_DAYS_AGO)
  .map(([cid, data]) => ({
    json: {
      rep_id: REP_ID,
      customer_name: custNameMap[cid] || cid,
      last_purchase_date: data.lastDate.toISOString().slice(0, 10),
      days_inactive: Math.floor((now - data.lastDate) / 86400000),
      lifetime_revenue: Math.round(data.totalRev * 100) / 100,
      snapshot_date: today
    }
  }));

// Return at least one empty item if no fallen angels
if (fallenAngels.length === 0) {
  return [{ json: { _empty: true, rep_id: REP_ID, snapshot_date: today } }];
}
return fallenAngels;
